head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnGridItemset]<br/>Body Column 정보를 사용하여 특정 Column 의 아이템 바인딩을 GridViewItemset 으로 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 아이템 바인딩을 GridViewItemset 으로 설정할 Body Column 의 ID 를 설정합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 파라미터 콤보 기본값 설정 (정적 select1 은 초기 selectedIndex 미적용 -> onpageload 에서 setValue)
    par_columnInfo.setValue("bsel");
    par_nodeset.setValue("data:dlt_new");
    par_label.setValue("nName");
    par_value.setValue("nVal");
    par_width.setValue("400");
    par_height.setValue("200");

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Body 에 select / autoComplete 컬럼을 dlt_grade(gLabel/gCode) 로 초기 바인딩
//  - text 컬럼(미동작 대조) 배치
//  - GridViewItemset 소스 DataList(dlt_new) : nVal/nName/nDept/nTel (다중 컬럼)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_new !== 'undefined') {
        $p.data.remove("dlt_new");
    }
    if (typeof dlt_body !== 'undefined') {
        $p.data.remove("dlt_body");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] bsel:select / baut:autoComplete 컬럼은 dlt_grade 초기 바인딩. btxt:text 는 미동작 대조.\n[절차] par(columnInfo(ID)·nodeset/label/value·width/height) 선택 후 (setColumnGridItemset) 클릭.\n[확인] columnInfo 를 ID 로 지정해도 select/autoComplete 는 dlt_new 로 재바인딩·재렌더(표시값 김철수). btxt 는 미동작.\n[리스트창] 대상 셀 편집 시 열리는 아이템 리스트창(그리드형 팝업)의 실측 크기 출력 - width 는 설정값(미설정 시 Body Column 너비) 반영, height 는 행수 기준 렌더."', '', 'label1');

    // 초기 아이템 DataList (gCode=value, gLabel=label)
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="gCode" name="gCode" dataType="text"></w2:column>';
    strGrade += '<w2:column id="gLabel" name="gLabel" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "gCode": "A", "gLabel": "최우수" },
        { "gCode": "B", "gLabel": "우수" },
        { "gCode": "C", "gLabel": "보통" }
    ], false);

    // GridViewItemset 소스 DataList (다중 컬럼) - setColumnGridItemset 으로 새로 바인딩
    let strNew = '';
    strNew += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_new" baseNode="list" repeatNode="map">';
    strNew += '<w2:columnInfo>';
    strNew += '<w2:column id="nVal" name="nVal" dataType="text"></w2:column>';
    strNew += '<w2:column id="nName" name="nName" dataType="text"></w2:column>';
    strNew += '<w2:column id="nDept" name="nDept" dataType="text"></w2:column>';
    strNew += '<w2:column id="nTel" name="nTel" dataType="text"></w2:column>';
    strNew += '</w2:columnInfo>';
    strNew += '<w2:data use="true"></w2:data>';
    strNew += '</w2:dataList>';
    $p.data.create(strNew);
    dlt_new.setJSON([
        { "nVal": "E01", "nName": "김철수", "nDept": "영업부", "nTel": "010-1111-0001" },
        { "nVal": "E02", "nName": "이영희", "nDept": "개발부", "nTel": "010-2222-0002" },
        { "nVal": "E03", "nName": "박민수", "nDept": "인사부", "nTel": "010-3333-0003" },
        { "nVal": "E04", "nName": "정수진", "nDept": "총무부", "nTel": "010-4444-0004" }
    ], false);

    // Body 데이터용 DataList (select/autoComplete 컬럼 초기값은 gCode)
    let strBody = '';
    strBody += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_body" baseNode="list" repeatNode="map">';
    strBody += '<w2:columnInfo>';
    strBody += '<w2:column id="bkey" name="bkey" dataType="text"></w2:column>';
    strBody += '<w2:column id="bsel" name="bsel" dataType="text"></w2:column>';
    strBody += '<w2:column id="baut" name="baut" dataType="text"></w2:column>';
    strBody += '<w2:column id="btxt" name="btxt" dataType="text"></w2:column>';
    strBody += '</w2:columnInfo>';
    strBody += '<w2:data use="true"></w2:data>';
    strBody += '</w2:dataList>';
    $p.data.create(strBody);
    dlt_body.setJSON([
        { "bkey": "1001", "bsel": "B", "baut": "B", "btxt": "메모A" },
        { "bkey": "1002", "bsel": "A", "baut": "A", "btxt": "메모B" },
        { "bkey": "1003", "bsel": "C", "baut": "C", "btxt": "메모C" },
        { "bkey": "1004", "bsel": "A", "baut": "B", "btxt": "메모D" }
    ], false);

    // Property 설정
    let properties = {
        dataList: "data:dlt_body",
        editable: "true",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // Body 초기 아이템 바인딩 조각 (select/autoComplete 셀용) : label ref=gLabel, value ref=gCode
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="gLabel"></w2:label><w2:value ref="gCode"></w2:value></w2:itemset></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:560px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setColumnGridItemset 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="70" id="hkey" value="키"></w2:column>';
    strTarget += '<w2:column width="150" id="hsel" value="select"></w2:column>';
    strTarget += '<w2:column width="150" id="haut" value="autoComplete"></w2:column>';
    strTarget += '<w2:column width="150" id="htxt" value="text"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    // bkey : text (키)
    strTarget += '<w2:column width="70" inputType="text" id="bkey" dataList="bkey" displayType="label"></w2:column>';
    // bsel : select  -> setColumnGridItemset 동작 대상
    strTarget += '<w2:column width="150" inputType="select" id="bsel" dataList="bsel">' + itemset + '</w2:column>';
    // baut : autoComplete -> setColumnGridItemset 동작 대상
    strTarget += '<w2:column width="150" inputType="autoComplete" id="baut" dataList="baut">' + itemset + '</w2:column>';
    // btxt : text (미동작 대조)
    strTarget += '<w2:column width="150" inputType="text" id="btxt" dataList="btxt" displayType="label"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 대상 컬럼 셀(Row 0)의 표시 텍스트 (재렌더 확인용) - 컬럼 ID -> 인덱스 변환
scwin.getCellDisplay = function (colId) {
    let colIndex = target1.getColumnIndex(colId);
    let td = document.querySelector("td[id$='target1_cell_0_" + colIndex + "']");
    return td ? td.textContent.trim() : "(td 없음)";
}



// GridViewItemset 아이템 리스트창(그리드형 드롭다운 팝업) 실측
//  - 팝업 컨테이너 : class="w2gridItemTable" (select/autoComplete 공통), 셀 편집 진입 시 렌더
scwin.measureItemPopup = function () {
    let els = document.querySelectorAll(".w2gridItemTable");
    for (let i = 0; i < els.length; i++) {
        let el = els[i];
        let r = el.getBoundingClientRect();
        if (r.width > 0 && window.getComputedStyle(el).display !== "none") {
            return { w: Math.round(r.width), h: Math.round(r.height) };
        }
    }
    return null;
}



// setColumnGridItemset 실행 (메인 검증) - columnInfo 를 컬럼 ID(문자열) 로 지정
//  - 검증 getter : getColumnNodeSet (GridViewItemset 은 nodeset/label/value + items(ref/header) 반환)
scwin.btn_setColumnGridItemset_onclick = function () {
    let colId = par_columnInfo.getValue();

    // info 파라미터 구성 (nodeset/label/value/item 필수, width/height 선택)
    let ns = par_nodeset.getValue() || "data:dlt_new";
    let lb = par_label.getValue() || "nName";
    let vl = par_value.getValue() || "nVal";
    let info = {
        "nodeset": ns,
        "label": lb,
        "value": vl,
        "item": [
            { "ref": "nVal", "header": "사번" },
            { "ref": "nName", "header": "이름" },
            { "ref": "nDept", "header": "부서" },
            { "ref": "nTel", "header": "연락처" }
        ]
    };
    let wVal = par_width.getValue();
    if (wVal !== "") {
        info.width = parseInt(wVal, 10);
    }
    let hVal = par_height.getValue();
    if (hVal !== "") {
        info.height = parseInt(hVal, 10);
    }

    // 재바인딩 전 표시값 (재렌더 확인용)
    let beforeCell = scwin.getCellDisplay(colId);
    let before = target1.getColumnNodeSet(colId);

    // columnInfo(필수:ID), info(필수:객체)
    target1.setColumnGridItemset(colId, info);

    setTimeout(function () {
        let after = target1.getColumnNodeSet(colId);
        let afterStr = after ? ("nodeset=" + after.nodeset + ", label=" + after.label + ", value=" + after.value) : "바인딩 없음";
        let itemStr = (after && after.items) ? after.items.map(function (it) { return it.header + "(" + it.ref + ")"; }).join(", ") : "없음";
        let changed = JSON.stringify(before) !== JSON.stringify(after);
        let isBound = !!(after && after.nodeset === ns);

        // 재바인딩된 컬럼(select/autoComplete)만 전 Row 를 dlt_new 첫 아이템(E01=김철수)으로 초기선택 -> 재렌더 확인
        if (isBound) {
            for (let r = 0; r < dlt_body.getRowCount(); r++) {
                dlt_body.setCellData(r, colId, "E01");
            }
        }

        // 공통 출력 (리스트창 실측값 sizeStr 포함)
        let flush = function (sizeStr) {
            let afterCell = scwin.getCellDisplay(colId);
            wf_body_bottom.getObj("scwin").setReturnValue("바인딩 변경 : " + changed);
            wf_body_bottom.getObj("scwin").setReturnValue("재바인딩 후 : " + afterStr);
            wf_body_bottom.getObj("scwin").setReturnValue("item : " + itemStr);
            wf_body_bottom.getObj("scwin").setReturnValue("재렌더 표시값 : " + beforeCell + " -> " + afterCell);
            wf_body_bottom.getObj("scwin").setReturnValue("리스트창 실측(px) : " + sizeStr + " [설정 width=" + (wVal || "미설정") + ", height=" + (hVal || "미설정") + "]");
        };

        setTimeout(function () {
            if (!isBound) {
                flush("해당 없음(미동작 컬럼)");
                return;
            }
            // 대상 셀(ID 로 지정) 편집 진입 -> 아이템 리스트창(그리드형 팝업) 오픈 후 실제 렌더 크기 측정
            let colIndex = target1.getColumnIndex(colId);
            let td = document.querySelector("td[id$='target1_cell_0_" + colIndex + "']");
            try { target1.setEditMode(td); } catch (e) {}
            setTimeout(function () {
                let m = scwin.measureItemPopup();
                let sizeStr = m ? ("width=" + m.w + ", height=" + m.h) : "측정 실패(팝업 미오픈)";
                // 리스트창(팝업) 닫기 : 외부 영역 mousedown 으로 selectbox 팝업 닫힘 (setEditMode(false) 는 내부 오류)
                document.body.dispatchEvent(new MouseEvent("mousedown", { bubbles: true }));
                flush(sizeStr);
            }, 450);
        }, 200);
    }, 300);
}
